// Web app manifest with paths under the base (/noirpad/) – icons are generated by scripts/prepare.mjs.
import type { APIRoute } from "astro";

export const GET: APIRoute = () => {
  const base = import.meta.env.BASE_URL.replace(/\/?$/, "/");
  const manifest = {
    name: "NoirPad",
    short_name: "NoirPad",
    description: "Markdown notes you can lock with a password – for Windows.",
    start_url: base,
    scope: base,
    display: "browser",
    background_color: "#0e0e10",
    theme_color: "#0e0e10",
    icons: [
      { src: `${base}icon-192.png`, sizes: "192x192", type: "image/png" },
      { src: `${base}icon-512.png`, sizes: "512x512", type: "image/png" },
      { src: `${base}icon-maskable-512.png`, sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
  return new Response(JSON.stringify(manifest, null, 2), { headers: { "Content-Type": "application/manifest+json" } });
};
